function Template(args: ButtonProps): JSX.Element {
  if (args.color === 'inherit') {
    return (
      <div
        className={`bg-pink-100 text-pink-700 rounded-md ${
          !args.fullWidth ? 'w-fit' : ''
        }`}
      >
        <Button {...args}>{args.children}</Button>
      </div>
    )
  }

  return <Button {...args}>{args.children}</Button>
}

export const Default = {
  render: Template,
}

export function FullWidth(): JSX.Element {
  return <Button fullWidth>Full width button</Button>
}
